package io.github.lifeofaitor.kitapagon.feature.map

import android.content.res.AssetManager
import java.io.File

/** The two bundled map styles, generated by tools/map-style (decision 0010). */
enum class MapTheme(
    val assetPath: String,
) {
    LIGHT("map/style/light.json"),
    DARK("map/style/dark.json"),
    ;

    companion object {
        fun forDarkMode(isDarkMode: Boolean): MapTheme = if (isDarkMode) DARK else LIGHT
    }
}

/** Builds the style of a package by pointing the bundled style template at its map file. */
object MapStyleTemplate {
    const val PACKAGE_MAP_PLACEHOLDER = "pmtiles://PACKAGE_MAP_URL"

    fun bindToMapFile(
        styleTemplate: String,
        mapFile: File,
    ): String {
        require(styleTemplate.contains(PACKAGE_MAP_PLACEHOLDER)) {
            "The map style has no $PACKAGE_MAP_PLACEHOLDER placeholder; regenerate it with tools/map-style."
        }
        return styleTemplate.replace(PACKAGE_MAP_PLACEHOLDER, "pmtiles://file://${mapFile.absolutePath}")
    }
}

internal fun AssetManager.readMapStyle(theme: MapTheme): String =
    open(theme.assetPath).bufferedReader().use { reader -> reader.readText() }
